/*!40000 ALTER TABLE `faq` DISABLE KEYS */;
INSERT INTO `faq` VALUES (1,'hama wereng','Hama wereng bisa diatasi dengan: 1) Tanam varietas tahan wereng, 2) Gunakan pestisida nabati, 3) Jaga kebersihan lahan, 4) Konsultasi dengan PPL setempat.','2026-08-25 02:30:18'),(2,'pupuk padi','Pupuk yang direkomendasikan untuk padi: 1) Urea (fase vegetatif), 2) SP-36 (fase generatif), 3) KCl (fase pengisian bulir). Gunakan dosis sesuai rekomendasi PPL.','2026-08-25 02:30:18'),(3,'cara tanam padi','Cara tanam padi yang baik: 1) Pilih bibit unggul, 2) Rendam benih 24 jam, 3) Semai di persemaian, 4) Pindah tanam saat bibit berumur 15-21 hari, 5) Jaga jarak tanam 20x20 cm.','2026-08-25 02:30:18'),(4,'panen padi','Ciri-ciri padi siap panen: 1) 80-90% gabah menguning, 2) Batang mulai mengering, 3) Gabah keras jika ditekan. Waktu panen yang baik adalah pagi hari saat cuaca cerah.','2026-08-25 02:30:18'),(5,'penyakit padi','Penyakit umum padi: 1) Blas (daun bercak), 2) Hawar daun, 3) Tungro (virus). Cara pencegahan: tanam varietas tahan, jaga jarak tanam, dan konsultasi dengan PPL.','2026-08-25 02:30:18'),(6,'cara ganti foto profil','Cara ganti foto profil: 1) Login ke akun Anda, 2) Klik menu \"🖼️ Ganti Foto\" di sidebar kiri, 3) Klik tombol \"Pilih File\", pilih foto dari HP/komputer (format JPG/PNG, maks 2MB), 4) Klik tombol \"Upload Foto\", 5) Foto profil Anda akan langsung berubah.','2026-08-25 23:24:06'),(7,'cara ganti password','Cara ganti password: 1) Login ke akun Anda, 2) Klik menu \"Ganti Password\" di sidebar (jika tersedia), 3) Masukkan password lama dan password baru, 4) Klik tombol \"Simpan\", 5) Password Anda akan berubah.','2026-08-25 23:24:06'),(8,'cara update data lahan','Cara update data lahan: 1) Login sebagai Petani, 2) Klik menu \"📋 Data Lahan\" di sidebar, 3) Cari lahan yang ingin diubah, 4) Klik tombol \"Edit\" (icon pensil), 5) Ubah data yang diperlukan (luas, jenis padi, tanggal tanam, dll), 6) Klik tombol \"Simpan Perubahan\".','2026-08-25 23:24:06'),(9,'cara tambah lahan','Cara tambah lahan baru: 1) Login sebagai Petani, 2) Klik menu \"➕ Tambah Lahan\" di sidebar, 3) Isi form (Nama Lahan, Lokasi, Luas, Jenis Padi, Tanggal Tanam), 4) Klik tombol \"🌾 Simpan Lahan\", 5) Data lahan akan tersimpan dan muncul di menu \"📋 Data Lahan\".','2026-08-25 23:24:06'),(10,'cara verifikasi akun','Cara verifikasi akun petani (untuk Perangkat Desa): 1) Login sebagai Perangkat Desa, 2) Klik menu \"✅ Verifikasi Akun\" di sidebar, 3) Lihat daftar petani yang statusnya \"pending\", 4) Klik tombol \"✅ Aktifkan\" untuk mengaktifkan akun, atau \"❌ Tolak\" untuk menolak akun, 5) Petani yang diaktifkan akan bisa login.','2026-08-25 23:24:06'),(11,'cara lihat data petani','Cara lihat data semua petani (untuk Perangkat Desa): 1) Login sebagai Perangkat Desa, 2) Klik menu \"👨‍🌾 Data Petani\" di sidebar, 3) Akan muncul tabel berisi semua petani yang terdaftar, 4) Anda bisa melihat NIK, nama, alamat, status, dan tanggal daftar petani.','2026-08-25 23:24:06'),(12,'cara lihat rekap desa','Cara lihat rekap pertanian desa (untuk Perangkat Desa): 1) Login sebagai Perangkat Desa, 2) Klik menu \"📊 Rekap Desa\" di sidebar, 3) Akan muncul data statistik: total petani, total lahan, total luas lahan, dan status lahan (tanam/tumbuh/panen).','2026-08-25 23:24:06'),(13,'cara kelola user','Cara kelola user (untuk Admin): 1) Login sebagai Admin, 2) Klik menu \"👥 Kelola User\" di sidebar, 3) Akan muncul tabel semua user, 4) Anda bisa mengubah status (aktif/blokir/pending) atau role (admin/petani/desa) dengan mengklik tombol yang tersedia, 5) Klik tombol \"✏️ Edit\" untuk mengedit data petani.','2026-08-25 23:24:06'),(14,'cara setting desa','Cara setting desa (untuk Admin): 1) Login sebagai Admin, 2) Klik menu \"⚙️ Setting Desa\" di sidebar, 3) Isi form data desa (Nama Desa, Kecamatan, Kabupaten, Kontak, Default Hasil Panen), 4) Klik tombol \"💾 Simpan Setting Desa\", 5) Data desa akan berubah dan digunakan di seluruh web.','2026-08-25 23:24:06'),(15,'cara backup data','Cara backup database (untuk Admin): 1) Login sebagai Admin, 2) Klik menu \"💾 Backup Data\" di sidebar, 3) Klik tombol \"💾 Download Backup\", 4) File backup (.sql) akan otomatis terdownload, 5) Simpan file backup di tempat aman untuk keamanan data.','2026-08-25 23:24:06'),(16,'cara login','Cara login ke web: 1) Buka halaman utama web, 2) Klik tombol \"Login\" di pojok kanan atas, 3) Masukkan NIK dan Password yang sudah terdaftar, 4) Klik tombol \"Login\", 5) Anda akan masuk ke dashboard sesuai role (Admin/Petani/Perangkat Desa).','2026-08-25 23:24:06'),(17,'cara daftar akun','Cara daftar akun petani: 1) Buka halaman utama web, 2) Klik tombol \"Daftar\" di pojok kanan atas, 3) Isi form pendaftaran (NIK 16 digit, Nama, No HP, Alamat, Password), 4) Klik tombol \"Daftar\", 5) Akun Anda akan terdaftar dengan status \"pending\", 6) Tunggu verifikasi dari Perangkat Desa untuk bisa login.','2026-08-25 23:24:06'),(18,'cara login','Cara login: 1) Buka halaman utama web, 2) Klik tombol \"Login\" di pojok kanan atas, 3) Masukkan NIK dan Password yang sudah terdaftar, 4) Klik tombol \"Login\", 5) Anda akan masuk ke dashboard sesuai role (Admin/Petani/Perangkat Desa).','2026-09-12 01:40:52'),(19,'cara daftar akun','Cara daftar akun petani: 1) Buka halaman utama web, 2) Klik tombol \"Daftar\" di pojok kanan atas, 3) Isi form pendaftaran (NIK 16 digit, Nama, No HP, Alamat, Password), 4) Klik tombol \"Daftar\", 5) Akun Anda akan terdaftar dengan status \"pending\", 6) Tunggu verifikasi dari Perangkat Desa untuk bisa login.','2026-09-12 01:40:52'),(20,'cara tambah lahan','Cara tambah lahan baru: 1) Login sebagai Petani, 2) Klik menu \"➕ Tambah Lahan\" di sidebar, 3) Isi form (Nama Lahan, Lokasi, Luas, Jenis Padi, Tanggal Tanam), 4) Klik tombol \"🌾 Simpan Lahan\", 5) Data lahan akan tersimpan dan muncul di menu \"📋 Data Lahan\".','2026-09-12 01:40:52'),(21,'cara lihat data lahan','Cara lihat data lahan: 1) Login sebagai Petani, 2) Klik menu \"📋 Data Lahan\" di sidebar, 3) Akan muncul tabel berisi semua lahan yang sudah Anda daftarkan, 4) Anda bisa melihat Nama Lahan, Lokasi, Luas, Jenis Padi, Tanggal Tanam, Perkiraan Panen, dan Status.','2026-09-12 01:40:52'),(22,'cara ganti foto profil','Cara ganti foto profil: 1) Login ke akun Anda, 2) Klik menu \"🖼️ Ganti Foto\" di sidebar kiri, 3) Klik tombol \"Pilih File\", pilih foto dari HP/komputer (format JPG/PNG, maks 2MB), 4) Klik tombol \"Upload Foto\", 5) Foto profil Anda akan langsung berubah.','2026-09-12 01:40:52'),(23,'cara ganti password','Cara ganti password: 1) Login ke akun Anda, 2) Klik menu \"🔑 Ganti Password\" di sidebar, 3) Masukkan password lama dan password baru, 4) Klik tombol \"Simpan Password\", 5) Password Anda akan berubah.','2026-09-12 01:40:52'),(24,'cara pakai ai asisten','Cara pakai AI Asisten: 1) Login sebagai Petani, 2) Klik menu \"🤖 AI Asisten\" di sidebar, 3) Ketik pertanyaan Anda di kolom chat, 4) Klik tombol kirim, 5) AI akan menjawab berdasarkan database FAQ.','2026-09-12 01:40:52'),(25,'cara export excel','Cara export data ke Excel: 1) Buka halaman yang mau di-export (Data Lahan / Rekap Desa / Log Aktivitas), 2) Klik tombol \"📥 Export Excel\" di pojok kanan atas, 3) File .xls akan otomatis ke-download, 4) Buka file pake Microsoft Excel atau Google Sheets.','2026-09-12 01:40:52'),(26,'cara verifikasi akun','Cara verifikasi akun petani (untuk Perangkat Desa): 1) Login sebagai Perangkat Desa, 2) Klik menu \"✅ Verifikasi Akun\" di sidebar, 3) Lihat daftar petani yang statusnya \"pending\", 4) Klik tombol \"✅ Aktifkan\" untuk mengaktifkan akun, atau \"❌ Tolak\" untuk menolak akun, 5) Petani yang diaktifkan akan bisa login.','2026-09-12 01:40:52'),(27,'cara lihat notifikasi','Cara lihat notifikasi: 1) Login sebagai Petani, 2) Lihat icon 🔔 di pojok kanan atas dashboard, 3) Kalo ada badge merah, berarti ada notifikasi baru, 4) Klik icon 🔔 untuk melihat daftar notifikasi, 5) Klik notifikasi untuk membuka detailnya.','2026-09-12 01:40:52'),(28,'daun padi menguning','Daun padi menguning bisa disebabkan oleh: 1) Kekurangan nitrogen (pupuk urea), 2) Serangan hama wereng, 3) Penyakit blas, 4) Kekurangan air. Solusi: 1) Tambahkan pupuk urea 100-200 kg/ha, 2) Cek apakah ada hama wereng, 3) Gunakan fungisida kalo ada penyakit, 4) Pastikan air cukup. Konsultasi dengan PPL setempat untuk penanganan lebih lanjut.','2026-09-12 01:40:52'),(29,'daun padi kering','Daun padi kering bisa disebabkan oleh: 1) Kekurangan air (kekeringan), 2) Serangan hama penggerek batang, 3) Penyakit hawar daun, 4) Keracunan pupuk. Solusi: 1) Tambahkan air, 2) Cek batang padi apakah ada lubang (penggerek), 3) Gunakan fungisida, 4) Kurangi dosis pupuk. Konsultasi dengan PPL setempat.','2026-09-12 01:40:52'),(30,'daun padi menggulung','Daun padi menggulung bisa disebabkan oleh: 1) Hama wereng coklat, 2) Hama putih palsu, 3) Kekurangan air. Solusi: 1) Gunakan insektisida untuk wereng, 2) Cek apakah ada ulat di dalam gulungan, 3) Tambahkan air. Konsultasi dengan PPL setempat.','2026-09-12 01:40:52'),(31,'daun padi berlubang','Daun padi berlubang bisa disebabkan oleh: 1) Hama ulat grayak, 2) Hama belalang, 3) Hama penggerek daun. Solusi: 1) Gunakan insektisida, 2) Kumpulkan dan musnahkan hama secara manual, 3) Jaga kebersihan lahan. Konsultasi dengan PPL setempat.','2026-09-12 01:40:52'),(32,'daun padi bercak coklat','Daun padi bercak coklat bisa disebabkan oleh: 1) Penyakit blas, 2) Penyakit hawar daun, 3) Penyakit bercak daun. Solusi: 1) Gunakan fungisida, 2) Tanam varietas tahan penyakit, 3) Jaga jarak tanam, 4) Kurangi kelembapan. Konsultasi dengan PPL setempat.','2026-09-12 01:40:52'),(33,'padi kerdil','Padi kerdil bisa disebabkan oleh: 1) Penyakit tungro (virus), 2) Kekurangan hara, 3) Serangan hama wereng. Solusi: 1) Cabut dan musnahkan tanaman yang terinfeksi, 2) Gunakan varietas tahan tungro, 3) Tambahkan pupuk lengkap, 4) Kendalikan wereng. Konsultasi dengan PPL setempat.','2026-09-12 01:40:52'),(34,'padi tidak berbulir','Padi tidak berbulir bisa disebabkan oleh: 1) Serangan hama wereng saat fase generatif, 2) Kekurangan air saat pengisian bulir, 3) Suhu terlalu ekstrem, 4) Kekurangan pupuk kalium. Solusi: 1) Kendalikan wereng, 2) Pastikan air cukup, 3) Tambahkan pupuk KCl, 4) Tanam varietas yang sesuai. Konsultasi dengan PPL setempat.','2026-09-12 01:40:52'),(35,'padi rebah','Padi rebah bisa disebabkan oleh: 1) Terlalu banyak pupuk nitrogen, 2) Angin kencang, 3) Hujan lebat, 4) Batang lemah. Solusi: 1) Kurangi pupuk nitrogen, 2) Tambahkan pupuk kalium (KCl), 3) Tanam varietas batang kuat, 4) Atur jarak tanam. Konsultasi dengan PPL setempat.','2026-09-12 01:40:52'),(36,'bulir padi kosong','Bulir padi kosong bisa disebabkan oleh: 1) Serangan hama wereng saat pengisian bulir, 2) Kekurangan air, 3) Suhu ekstrem, 4) Kekurangan hara. Solusi: 1) Kendalikan wereng, 2) Pastikan air cukup, 3) Tambahkan pupuk, 4) Tanam varietas yang sesuai. Konsultasi dengan PPL setempat.','2026-09-12 01:40:52'),(37,'akar padi rusak','Akar padi rusak bisa disebabkan oleh: 1) Hama orong-orong, 2) Penyakit akar, 3) Kekurangan oksigen (tanah terlalu basah), 4) Keracunan. Solusi: 1) Gunakan insektisida untuk orong-orong, 2) Gunakan fungisida, 3) Perbaiki drainase, 4) Kurangi pupuk berlebihan. Konsultasi dengan PPL setempat.','2026-09-12 01:40:52'),(38,'pupuk padi yang bagus','Pupuk yang direkomendasikan untuk padi: 1) Urea (fase vegetatif, 200-300 kg/ha), 2) SP-36 (fase generatif, 100-150 kg/ha), 3) KCl (fase pengisian bulir, 100-150 kg/ha), 4) Pupuk organik (kompos). Gunakan dosis sesuai rekomendasi PPL setempat.','2026-09-12 01:40:52'),(39,'waktu pemupukan padi','Waktu pemupukan padi yang tepat: 1) Pemupukan pertama (7-10 HST): Urea + SP-36, 2) Pemupukan kedua (25-30 HST): Urea + KCl, 3) Pemupukan ketiga (50-60 HST): Urea + KCl. Sesuaikan dengan kondisi tanaman & rekomendasi PPL.','2026-09-12 01:40:52'),(40,'cara mengatasi hama wereng','Cara mengatasi hama wereng: 1) Tanam varietas tahan wereng (IR64, Ciherang), 2) Gunakan insektisida (BPMC, Imidakloprid), 3) Jaga kebersihan lahan, 4) Atur jarak tanam, 5) Kendalikan secara terpadu (PHT). Konsultasi dengan PPL setempat.','2026-09-12 01:40:52'),(41,'cara mengatasi hama penggerek batang','Cara mengatasi hama penggerek batang: 1) Kumpulkan dan musnahkan ngengat, 2) Gunakan insektisida (Karbofuran, Diazinon), 3) Tanam varietas tahan, 4) Jaga kebersihan lahan, 5) Rotasi tanaman. Konsultasi dengan PPL setempat.','2026-09-12 01:40:52'),(42,'cara mengatasi penyakit blas','Cara mengatasi penyakit blas: 1) Gunakan fungisida (Trisiklazol, Propikonazol), 2) Tanam varietas tahan blas, 3) Jaga jarak tanam, 4) Kurangi pupuk nitrogen, 5) Jaga kelembapan. Konsultasi dengan PPL setempat.','2026-09-12 01:40:52'),(43,'cara mengatasi penyakit tungro','Cara mengatasi penyakit tungro: 1) Cabut dan musnahkan tanaman terinfeksi, 2) Kendalikan wereng hijau (vektor), 3) Tanam varietas tahan tungro, 4) Jaga kebersihan lahan, 5) Rotasi tanaman. Konsultasi dengan PPL setempat.','2026-09-12 01:40:52'),(44,'ciri padi siap panen','Ciri-ciri padi siap panen: 1) 80-90% gabah menguning, 2) Batang mulai mengering, 3) Gabah keras jika ditekan, 4) Malai mulai merunduk, 5) Umur tanaman 100-120 hari setelah tanam. Waktu panen yang baik: pagi hari saat cuaca cerah.','2026-09-12 01:40:52'),(45,'cara panen padi yang baik','Cara panen padi yang baik: 1) Panen saat cuaca cerah, 2) Gunakan sabit atau mesin panen, 3) Potong batang sekitar 20-30 cm dari tanah, 4) Kumpulkan gabah di tempat yang kering, 5) Jemur gabah 2-3 hari sampai kering, 6) Simpan di tempat kering.','2026-09-12 01:40:52'),(46,'cara menyimpan gabah','Cara menyimpan gabah: 1) Jemur gabah sampai kadar air 14%, 2) Simpan di tempat kering & berventilasi, 3) Gunakan karung atau silo, 4) Jauhkan dari hama (tikus, serangga), 5) Cek secara berkala. Gabah kering bisa disimpan 3-6 bulan.','2026-09-12 01:40:52'),(47,'perkiraan hasil panen','Perkiraan hasil panen padi: 1) Padi genjah: 4-6 ton/ha, 2) Padi dalam: 5-7 ton/ha, 3) Padi hibrida: 7-10 ton/ha. Hasil tergantung varietas, pupuk, air, & perawatan. Konsultasi dengan PPL setempat untuk hasil maksimal.','2026-09-12 01:40:52');
/*!40000 ALTER TABLE `faq` ENABLE KEYS */;
