DROP TABLE IF EXISTS `lahan`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lahan` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `nama_lahan` varchar(100) NOT NULL,
  `lokasi` varchar(255) DEFAULT NULL,
  `luas` decimal(10,2) NOT NULL,
  `jenis_padi` varchar(50) NOT NULL,
  `tgl_tanam` date NOT NULL,
  `tgl_panen_perkiraan` date NOT NULL,
  `status` enum('tanam','tumbuh','panen','selesai') NOT NULL DEFAULT 'tanam',
  `catatan` text,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `fk_lahan_users` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
